15	/* ---------- Bootstrap overrides ----------
16	   Bootstrap is loaded for its grid only. Its base styles ("reboot") change
17	   fonts, spacing, and headings, so these put our original look back. */
18	:root { scroll-behavior: auto; }   /* the link popup measures right after scrolling */
19	body {
20	  margin: 0;
21	  font-family: "Inter", Arial, sans-serif;
22	  font-size: 1rem;   /* 16px; grows a little on very wide screens (see below) */
23	  line-height: normal;
24	  background: var(--navy);
25	  color: var(--text);
26	}
27	h1, h2, h3 { color: inherit; font-weight: bold; line-height: normal; }
28	h2 { font-size: 1.5em; margin: 0.83em 0; }
29	h3 { font-size: 1.17em; margin: 1em 0; }
30	p { margin: 1em 0; }
31	ul, ol { margin: 1em 0; padding-left: 40px; }
32	small { font-size: smaller; }
33	.container { max-width: 1200px; }   /* one width at every breakpoint, centered */
