44	.topbar { display: none; border-bottom: 1px solid rgba(159, 183, 201, 0.15); background: #0c1f3b; }
45	body:not([data-screen="start-screen"]) .hero { display: none; }
46	body:not([data-screen="start-screen"]) .topbar { display: block; }
47	.topbar-inner {
48	  padding-top: 8px; padding-bottom: 8px; min-height: 52px;
