57	async function apiGetScenario(mode, seen) {
58	  if (OFFLINE) {
59	    const pool = MOCK_SCENARIOS.filter((s) => s.difficulty === mode && !seen.includes(s.scenario_id));
60	    const s = pool[Math.floor(Math.random() * pool.length)];
61	    return { scenario_id: s.scenario_id, channel: s.channel, sender: s.sender, subject: s.subject, body: s.body, link: s.link };
62	  }
63	  return fetch(`/api/scenario?mode=${mode}&seen=${seen.join(",")}`).then((r) => r.json());
64	}
