66	async function apiAnswer(scenario_id, guess) {
67	  if (OFFLINE) {
68	    const s = MOCK_SCENARIOS.find((x) => x.scenario_id === scenario_id);
69	    return { correct: guess === s.game_answer, game_answer: s.game_answer, red_flags: s.red_flags, explanation: s.explanation };
70	  }
71	  return fetch("/api/answer", {
72	    method: "POST",
73	    headers: { "Content-Type": "application/json" },
74	    body: JSON.stringify({ scenario_id, guess }),
75	  }).then((r) => r.json());
76	}
