78	async function apiSaveScore(username, points, badge) {
79	  if (OFFLINE) {
80	    const board = JSON.parse(localStorage.getItem("ps-board") || "{}");
81	    const p = board[username] || { username, total_score: 0, badges: [] };
82	    p.total_score += points;
83	    if (badge && !p.badges.includes(badge)) p.badges.push(badge);
84	    board[username] = p;
85	    try { localStorage.setItem("ps-board", JSON.stringify(board)); } catch (e) {}
86	    return p;
87	  }
88	  return fetch("/api/score", {
89	    method: "POST",
90	    headers: { "Content-Type": "application/json" },
91	    body: JSON.stringify({ username, points, badge }),
92	  }).then((r) => r.json());
93	}
