95	async function apiLeaderboard() {
96	  if (OFFLINE) {
97	    let board = {};
98	    try { board = JSON.parse(localStorage.getItem("ps-board") || "{}"); } catch (e) {}
99	    return Object.values(board)
100	      .sort((a, b) => b.badges.length - a.badges.length || b.total_score - a.total_score)
101	      .slice(0, 10);
102	  }
103	  return fetch("/api/leaderboard").then((r) => r.json());
104	}
