592	$("btn-phish").addEventListener("click", () => answer("Phish"));
593	$("btn-legit").addEventListener("click", () => answer("Legit"));
594	$("btn-next").addEventListener("click", () => (round < ROUNDS ? nextRound() : finish()));
595	
596	// ---------- Badge reveal ----------
597	const CONFETTI_COLORS = ["#2de0c4", "#3ddc84", "#ffd166", "#ff5d6c", "#8ecae6", "#ffffff"];
598	
599	// Replays a CSS animation that has already run once this session.
600	function replayAnimation(el) {
601	  el.style.animation = "none";
602	  void el.offsetWidth;
603	  el.style.animation = "";
604	}
605	
606	function burstConfetti() {
607	  const layer = $("confetti");
608	  layer.innerHTML = "";
609	  if (calmMode()) return;
610	  for (let i = 0; i < 30; i++) {
611	    const bit = document.createElement("span");
612	    bit.className = "confetti-bit";
613	    bit.style.left = `${Math.random() * 100}%`;
614	    bit.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
615	    bit.style.setProperty("--dx", `${(Math.random() - 0.5) * 240}px`);
616	    bit.style.setProperty("--rot", `${Math.random() * 900 - 450}deg`);
617	    bit.style.animationDelay = `${Math.random() * 0.35}s`;
618	    bit.style.animationDuration = `${1.5 + Math.random()}s`;
619	    if (i % 3 === 0) bit.style.borderRadius = "50%";
620	    layer.appendChild(bit);
621	  }
622	  setTimeout(() => { layer.innerHTML = ""; }, 3200);
623	}
624	
625	function revealBadge(isMaster) {
626	  const [icon, ...name] = BADGES[mode].split(" ");
627	  $("badge-art").textContent = icon;
628	  $("badge-name").textContent = name.join(" ");
629	  $("badge-reveal").classList.remove("hidden");
630	  replayAnimation($("badge-art"));
631	  replayAnimation($("badge-name"));
632	
633	  if (isMaster) {
634	    $("badge-master").textContent = "🏆 PhishSense Master: all three badges earned!";
635	    $("badge-master").classList.remove("hidden");
636	    replayAnimation($("badge-master"));
637	  } else {
638	    $("badge-master").classList.add("hidden");
639	  }
640	  burstConfetti();
641	}
642	
643	// No badge this run: a hook takes the badge's place at the top of the card
644	function showMissedBadge() {
645	  $("badge-art").textContent = "🪝";
646	  $("badge-name").textContent = "";
647	  $("badge-master").classList.add("hidden");
648	  $("confetti").innerHTML = "";
649	  $("badge-reveal").classList.remove("hidden");
650	  replayAnimation($("badge-art"));
651	}
652	
653	// ---------- End of run ----------
654	function renderRecap() {
655	  // Group the same red flag together so repeats show as a count.
656	  const groups = new Map();
657	  missed.forEach((flag) => {
658	    const key = flag.toLowerCase().replace(/\s+/g, " ");
659	    const hit = groups.get(key);
660	    if (hit) hit.n++;
661	    else groups.set(key, { text: flag, n: 1 });
662	  });
663	  const items = [...groups.values()].sort((a, b) => b.n - a.n);
664	
665	  $("recap").innerHTML = `<h3>Red flags you missed this run</h3>` + (items.length
666	    ? `<ul>${items.map((g) => `<li>${esc(g.text)}${g.n > 1 ? ` <span class="count">×${g.n}</span>` : ""}</li>`).join("")}</ul>`
667	    : `<p class="clean">You caught every red flag!</p>`);
668	  $("recap").classList.remove("hidden");
669	}
670	
671	async function finish() {
672	  const passed = correct >= TO_PASS;
673	  const badge = passed ? mode : null;
674	  const player = await apiSaveScore($("username").value.trim(), correct * PER_CORRECT, badge);
675	
676	  const owned = Array.isArray(player?.badges) ? player.badges : (passed ? [mode] : []);
677	  const isMaster = ALL_MODES.every((m) => owned.includes(m));
678	
679	  $("end-title").textContent = passed ? `You earned ${BADGES[mode]}!` : `${correct} of ${ROUNDS} correct`;
680	  $("end-text").textContent = passed
681	    ? "Nice catch. Try the next mode!"
682	    : `You need ${TO_PASS} to earn ${BADGES[mode]}. Every round is new, so try again!`;
683	
684	  if (passed) revealBadge(isMaster);
685	  else showMissedBadge();
686	
687	  renderRecap();
688	  show("end-screen");
689	  loadLeaderboard();
690	}
691	
692	$("btn-home").addEventListener("click", () => show("start-screen"));
693	
694	// ---------- Leaderboard ----------
695	// The same list is shown on the home screen and the end screen.
696	async function loadLeaderboard() {
697	  const rows = await apiLeaderboard();
698	  const html = rows.length
699	    ? rows.map((p) => {
700	        const icons = p.badges.map((b) => BADGES[b]?.split(" ")[0] || "").join(" ");
701	        const master = ALL_MODES.every((b) => p.badges.includes(b)) ? " 🏆" : "";
702	        return `<li><b>${esc(p.username)}</b> ${icons}${master} <span>${p.total_score} pts</span></li>`;
703	      }).join("")
704	    : '<li class="empty">No scores yet. Be the first!</li>';
705	  document.querySelectorAll(".leaderboard-list").forEach((el) => (el.innerHTML = html));
706	}
707	
708	const ready = checkBackend();
709	ready.then(loadLeaderboard);
