--green: #3ddc84;
/* Difficulty colors: buttons, badge icons, mission title */
--easy: #4ade80;     /* Minnow */
--medium: #facc15;   /* Angler */
--hard: #f87171;     /* Captain */
--easy-tint: rgba(74, 222, 128, 0.14);
--medium-tint: rgba(250, 204, 21, 0.14);
--hard-tint: rgba(248, 113, 113, 0.14);
--fit-h: none;

/* Each difficulty sets --tier; anything tagged with it (icons, the mission title) uses that color */
.tier-easy { --tier: var(--easy); --tier-tint: var(--easy-tint); }
.tier-medium { --tier: var(--medium); --tier-tint: var(--medium-tint); }
.tier-hard { --tier: var(--hard); --tier-tint: var(--hard-tint); }
.tier-easy, .tier-medium, .tier-hard { color: var(--tier); }

/* Badge icon: sized to the text around it, drawn in currentColor */
.badge-icon { display: inline-block; width: 1.15em; height: 1.15em; vertical-align: -0.2em; margin-right: 0.3em; }
.badge-label { white-space: nowrap; }

/* Difficulty buttons: colored border, light tint on hover, text stays white on the dark card */
button.mode {
  padding: 18px 8px; background: var(--navy-2); color: var(--text); border: 2px solid var(--tier);
  transition: background-color 0.15s ease;
}
button.mode:hover, button.mode:focus-visible {
  background: linear-gradient(var(--tier-tint), var(--tier-tint)) var(--navy-2);
}
button.mode:focus-visible { outline: 2px solid var(--tier); outline-offset: 2px; }
.mode .badge-icon { width: 1.3em; height: 1.3em; vertical-align: -0.3em; }
.mode small { color: var(--muted); font-weight: 400; }

.badge-art {
  font-size: 96px; line-height: 1.1;
  display: flex; justify-content: center;

  animation: fade-rise 0.5s ease-out 0.75s both;
}
.badge-art .badge-icon { width: 1em; height: 1em; margin: 0; vertical-align: 0; }
.badge-name.tier-easy, .badge-name.tier-medium, .badge-name.tier-hard { color: var(--tier); }

