// Drives headless Chrome over CDP and saves screenshots of each screen.
import { spawn } from "node:child_process";
import { writeFileSync, mkdirSync } from "node:fs";
const OUT = process.argv[2];
mkdirSync(OUT, { recursive: true });
const chrome = spawn("C:/Program Files/Google/Chrome/Application/chrome.exe",
  ["--headless=new", "--remote-debugging-port=9333", `--user-data-dir=${OUT}/profile`, "--hide-scrollbars", "about:blank"]);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let list;
for (let i = 0; i < 40; i++) { try { list = await (await fetch("http://127.0.0.1:9333/json/list")).json(); break; } catch { await sleep(250); } }
const page = list.find((t) => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let id = 0; const pending = new Map();
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } });
const send = (method, params = {}) => new Promise((r) => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const ev = async (expr) => (await send("Runtime.evaluate", { expression: expr, awaitPromise: true, returnByValue: true })).result?.result?.value;
const shot = async (name) => { await sleep(1800); const r = await send("Page.captureScreenshot", { format: "png", captureBeyondViewport: false }); writeFileSync(`${OUT}/${name}.png`, Buffer.from(r.result.data, "base64")); };

await send("Page.enable"); await send("Runtime.enable");
const errors = [];
ws.addEventListener("message", (e) => { const m = JSON.parse(e.data); if (m.method === "Runtime.exceptionThrown") errors.push(m.params.exceptionDetails.exception?.description); });

for (const [w, h, tag] of [[1920, 1080, "desk"], [375, 812, "phone"]]) {
  await send("Emulation.setDeviceMetricsOverride", { width: w, height: h, deviceScaleFactor: 1, mobile: tag === "phone" });
  await send("Page.navigate", { url: "http://localhost:5173/" }); await sleep(800);
  await ev(`localStorage.setItem("ps-board", JSON.stringify({Ana:{username:"Ana",total_score:1400,badges:["easy","medium","hard"]},Ben:{username:"Ben",total_score:800,badges:["easy","medium"]},Cy:{username:"Cy",total_score:400,badges:["easy"]}}))`);
  await send("Page.reload"); await sleep(1200);
  await ev(`document.body.classList.remove("fish-mode")`);
  // hover the Medium button
  const r = await ev(`(() => { const b = document.querySelector('[data-mode="medium"]').getBoundingClientRect(); return [b.x + b.width/2, b.y + b.height/2]; })()`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: r[0], y: r[1] });
  await shot(`${tag}-1-home`);
  for (const m of ["easy", "medium", "hard"]) {
    await ev(`document.getElementById("username").value = "Tester"; document.querySelector('[data-mode="${m}"]').click()`);
    await shot(`${tag}-2-mission-${m}`);
    await ev(`document.getElementById("btn-back").click()`);
  }
  await ev(`document.querySelector('[data-mode="hard"]').click(); document.getElementById("btn-start").click()`); await sleep(500);
  await ev(`results=[true,true,true,true,false]; correct=4; round=5; missed=["Mismatched sender domain"]; finish()`);
  await shot(`${tag}-3-end-pass`);
  await ev(`document.getElementById("btn-home").click(); document.querySelector('[data-mode="medium"]').click(); document.getElementById("btn-start").click()`); await sleep(500);
  await ev(`results=[true,false,true,false,false]; correct=2; round=5; missed=[]; finish()`);
  await shot(`${tag}-4-end-fail`);
}
console.log("errors:", JSON.stringify(errors));
ws.close(); chrome.kill();

